      final typeOk =
          type == null ||
          (type == 'f' && info.kind == FileKind.file) ||
          (type == 'd' && info.kind == FileKind.directory);
      final nameOk = nameRegex == null || nameRegex.hasMatch(info.name);
      if (typeOk && nameOk) out.writeln(display);
