  _StageResult _echo(List<String> args) {
    var newline = true;
    var interpretEscapes = false;
    var i = 0;
    while (i < args.length) {
      if (args[i] == '-n') {
        newline = false;
      } else if (args[i] == '-e') {
        interpretEscapes = true;
      } else if (args[i] == '-E') {
        interpretEscapes = false;
      } else {
        break;
      }
      i++;
