      switch (command) {
        'rg' => (module: rg, argv: const ['rg']),
        'find' => (module: find, argv: const ['find']),
        'sed' => (module: sed, argv: const ['sed']),
        'awk' => (module: awk, argv: const ['awk']),
        _ => null,
