      switch (command) {
        'tar' => (module: tar, argv: const ['tar']),
        'gzip' => (module: gzip, argv: const ['gzip']),
        'zip' => (module: zip, argv: const ['zip']),
        'unzip' => (module: zip, argv: const ['zip_util']),
        _ => null,
