  /// Consumes one `cat` operand into [out]. Returns the error line when
  /// the operand cannot be read, else null.
  Future<String?> _catSingle(
    String file,
    CatInvocation parsed,
    String? stdinText,
    String cwd,
    BytesBuilder out,
  ) async {
    if (file == '-') {
      out.add(utf8.encode(stdinText ?? ''));
      return null;
