  static void _catNumberedBytes(
    List<int> bytes,
    CatInvocation parsed,
    BytesBuilder out,
  ) {
    if (parsed.number || parsed.numberNonBlank) {
      out.add(
        utf8.encode(
          applyCatNumbering(
            utf8.decode(bytes, allowMalformed: true),
            nonBlankOnly: parsed.numberNonBlank,
