    switch (action) {
      case '-v':
      case '--verbose':
        return _remoteVerbose(repo);
      case 'add':
        return _remoteAdd(repo, args);
      case 'remove':
      case 'rm':
        return _remoteRemove(repo, args);
      case 'get-url':
        return _remoteGetUrl(repo, args);
