    dart_git.GitRepository repo,
    List<String> args,
  ) {
    final remoteName = args.isEmpty ? 'origin' : args.first;
    final remote = repo.config.remote(remoteName);
    if (remote == null) {
      return (
        error: "fatal: '$remoteName' does not appear to be a git repository",
        remoteName: remoteName,
        url: '',
