  Result<StageResult, ExecutionError> _gitCatFileRender(
    GitObject obj,
    String flag,
  ) {
    if (flag == '-t') {
      return Ok(
        StageResult(
          stdout: utf8.encode('${obj.formatStr()}\n'),
          stderr: const [],
          exitCode: 0,
        ),
      );
    }
    if (flag == '-p') {
      if (obj is GitBlob) {
        return Ok(
          StageResult(stdout: obj.blobData, stderr: const [], exitCode: 0),
        );
      }
      return Ok(
        StageResult(
          stdout: utf8.encode(
            '${utf8.decode(obj.serializeData(), allowMalformed: true)}\n',
